import type { API, FileInfo, ObjectExpression } from "jscodeshift"
import { getStringValue } from "../ast-helpers"

export const name = path.basename(__filename, path.extname(__filename))
export const description =
    'remove redundant `driver: require("expo-sqlite")` from Expo DataSource config'

// Reads the key name of an object property, supporting both identifier keys
// (`driver`) and string-literal keys (`"driver"`). Returns null for computed /
// numeric / other key shapes we don't want to match.
const getKeyName = (prop: {
    type: string
    key?: { type: string; name?: string }
}): string | null => {
    if (prop.type !== "Property" && prop.type !== "ObjectProperty") return null
    const key = prop.key
    if (!key) return null
    if (key.type === "Identifier") return key.name ?? null
    return getStringValue(key as any)
}

// True when the object carries BOTH `type: "expo"` and a `database` property.
// Both are required so we don't touch unrelated config objects that happen to
// reuse `type: "expo"` (or `driver`) for other purposes.
const isExpoDataSource = (obj: ObjectExpression): boolean => {
    let hasExpoType = false
    let hasDatabase = false

    for (const prop of obj.properties) {
        const keyName = getKeyName(prop as any)
        if (keyName === null) continue
        if (keyName === "type" && getStringValue((prop as any).value) === "expo") {
            hasExpoType = true
        } else if (keyName === "database") {
            hasDatabase = true
        }
    }

    return hasExpoType && hasDatabase
}

// True when the value node is exactly a `require("expo-sqlite")` call — a plain
// CallExpression, not a member access (`require("expo-sqlite").default`), an
// identifier, or a call to some other package.
const isRequireExpoSqlite = (value: any): boolean => {
    if (!value || value.type !== "CallExpression") return false
    const callee = value.callee
    if (!callee || callee.type !== "Identifier" || callee.name !== "require") {
        return false
    }
    const args = value.arguments
    if (!args || args.length !== 1) return false
    return getStringValue(args[0]) === "expo-sqlite"
}

export const datasourceExpo = (file: FileInfo, api: API) => {
    const j = api.jscodeshift
    const root = j(file.source)

    let hasChanges = false

    root.find(j.ObjectExpression).forEach((objPath) => {
        if (!isExpoDataSource(objPath.node)) return

        const original = objPath.node.properties.length

        objPath.node.properties = objPath.node.properties.filter((prop) => {
            if (getKeyName(prop as any) !== "driver") return true
            return !isRequireExpoSqlite((prop as any).value)
        })

        if (objPath.node.properties.length !== original) hasChanges = true
    })

    return hasChanges ? root.toSource() : undefined
}

export const fn = datasourceExpo
export default fn
